{
  "items": [
    {
      "name": "Finset.sum_le_card_nsmul",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {N : Type u_5} [inst : AddCommMonoid N] [inst_1 : PartialOrder N] [AddLeftMono N] (s : Finset ι)\n  (f : ι → N) (n : N), (∀ x ∈ s, f x ≤ n) → s.sum f ≤ s.card • n"
    },
    {
      "name": "Finset.card_nsmul_le_sum",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {N : Type u_5} [inst : AddCommMonoid N] [inst_1 : PartialOrder N] [AddLeftMono N] (s : Finset ι)\n  (f : ι → N) (n : N), (∀ x ∈ s, n ≤ f x) → s.card • n ≤ s.sum f"
    },
    {
      "name": "Multiset.sum_le_card_nsmul",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Multiset",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : AddCommMonoid α] [inst_1 : PartialOrder α] [AddLeftMono α] (s : Multiset α) (n : α),\n  (∀ (x : α), x ∈ s → x ≤ n) → s.sum ≤ s.card • n"
    },
    {
      "name": "Finset.card_nsmul_le",
      "module_name": "Mathlib.Algebra.Group.Pointwise.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : DecidableEq α] [inst_1 : AddMonoid α] {s : Finset α} {n : ℕ}, (n • s).card ≤ s.card ^ n"
    },
    {
      "name": "List.sum_le_card_nsmul",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.List",
      "kind": "theorem",
      "type": "∀ {M : Type u_3} [inst : AddMonoid M] [inst_1 : Preorder M] [AddRightMono M] [AddLeftMono M] (l : List M) (n : M),\n  (∀ (x : M), x ∈ l → x ≤ n) → l.sum ≤ l.length • n"
    }
  ]
}
